/*
	Spiral Galaxy #genuary1 #genuary #genuary2501
	Vertical or horizontal lines only
	https://openprocessing.org/sketch/2498632
	#generativeart #creativecoding #p5js
*/

let SZE = 12;
const MAR = 0.3; // margin for non filled areas

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	stroke(lerpColor(color("steelblue"), color("gold"), random()))
	strokeWeight(2);
	noiseSeed(~~random(999999));
}

function draw() {
	background(2, 2, 12);

	for (let y = 0; y < height; y += SZE) {		
		for (let x = 0; x < width; x += SZE) {
			const n = noise(x/231, y/231, frameCount/231);
			if (n < MAR) {
				// nothing
			} else if (n < 0.5) {
				line(x, y+SZE, x+SZE, y+SZE);
				// line(x, y+SZE/2, x+SZE, y+SZE/2);
			} else if (n < 1 - MAR) {
				line(x+SZE, y, x+SZE, y+SZE);
				// line(x+SZE/2, y, x+SZE/2, y+SZE);
			} else {
				// notinhg
			}
		}
	}

	drawMsg("Noise (epi) #genuary2501")
}

function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function drawMsg(msg) {
	push();
	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)
	pop();
}
